printf '\n=== identity ===\n'; id; uname -a; cat /proc/cpuinfo; cat /proc/device-tree/model; printf '\n'; for f in /etc/tizen-release /etc/os-release /etc/tizen-build.conf; do if test -r "$f"; then echo "=== $f ==="; cat "$f"; fi; done
printf '\n=== kernel config ===\n'; if test -r /proc/config.gz; then zcat /proc/config.gz | grep -E 'CONFIG_(CORESIGHT|ARM_PMU|HW_PERF_EVENTS|THUMB2_KERNEL|STRICT_DEVMEM|ARM64|64BIT)'; else echo '/proc/config.gz unavailable'; fi
printf '\n=== components ===\n'; ls -la /sys/bus/coresight/devices/; ls -la /sys/bus/event_source/devices/; printf '\n=== dmesg ===\n'; dmesg | grep -iE 'coresight|etm|ptm|tmc|tpiu|opencsd|pmu'; printf '\n=== perf ===\n'; command -v perf; perf --version; perf version --build-options; printf '\n=== perf list ===\n'; perf list; printf '\n=== permission ===\n'; cat /proc/sys/kernel/perf_event_paranoid; printf '\n__ETM_PROBE_DONE__\n'
